const payload = $input.first().json;
const pair = payload.pair || 'ETH/USDT';
const binanceFundingRate = payload.binanceFunding || 0.00035; // 0.035% per 8h
const bybitFundingRate = payload.bybitFunding || 0.00012;

// Annualized carry APR = rate * 3 * 365 * 100
const annualizedAprBinance = Math.round(binanceFundingRate * 3 * 365 * 10000) / 100;
const annualizedAprBybit = Math.round(bybitFundingRate * 3 * 365 * 10000) / 100;

const spotBinance = 3450.20;
const spotCoinbase = 3462.50;
const grossSpread = ((spotCoinbase - spotBinance) / spotBinance) * 100;
const netSpread = grossSpread - 0.15; // after 0.075% maker/taker fee

return {
  json: {
    pair,
    binanceFundingRate,
    annualizedAprBinance,
    annualizedAprBybit,
    spatialSpread: {
      venueA: 'Binance',
      priceA: spotBinance,
      venueB: 'Coinbase',
      priceB: spotCoinbase,
      netSpreadPercent: Math.round(netSpread * 100) / 100
    },
    isCarryViable: annualizedAprBinance > 15,
    isArbitrageViable: netSpread > 0.2
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'arbitrage-funding',
    botName: 'Crypto Arbitrage & Funding Rate Exploiter',
    strategy: 'DELTA_NEUTRAL_CASH_AND_CARRY',
    executionPlan: text,
    timestamp: new Date().toISOString()
  }
};
